from __future__ import annotations

import io
import tokenize
from pathlib import Path

ROOT = Path('.').resolve()
results: list[tuple[str, int]] = []

for path in sorted(ROOT.rglob('*.py')):
    if '.venv' in path.parts or 'node_modules' in path.parts:
        continue
    rel = path.relative_to(ROOT).as_posix()
    try:
        src = path.read_text(encoding='utf-8')
    except (UnicodeDecodeError, OSError):
        continue
    try:
        tokens = list(tokenize.generate_tokens(io.StringIO(src).readline))
    except (tokenize.TokenError, IndentationError, SyntaxError):
        # fallback: naive scan
        for i, line in enumerate(src.splitlines(), 1):
            idx = line.find('#')
            if idx != -1 and 'TODO' in line[idx:]:
                results.append((rel, i))
        continue
    for tok in tokens:
        if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
            results.append((rel, tok.start[0]))

results = sorted(set(results))
Path('todos.txt').write_text(''.join(f'{p}:{n}\n' for p, n in results), encoding='utf-8')
print(len(results))
for p, n in results:
    print(f'{p}:{n}')
